5: 
6: class ProfilePage extends StatefulWidget {
7:   const ProfilePage({super.key});
8: 
9:   @override
10:   State<ProfilePage> createState() => _ProfilePageState();
11: }
12: 
13: class _ProfilePageState extends State<ProfilePage> with SingleTickerProviderStateMixin {
14:   static final _tween = Tween<Alignment>(begin: Alignment.centerLeft, end: Alignment.centerRight);
15: 
16:   late final ValueNotifier<AppThemeMode> _themeModeNotifier = ValueNotifier(_settingsRepository.readThemeMode());
17: 
18:   late final AnimationController _alignmentController;
19:   late Animation<AlignmentGeometry> _alignmentAnimation;
20: 
21:   SettingsRepository get _settingsRepository => context.read<SettingsRepository>();
22: 
23:   @override
24:   void initState() {
25:     super.initState();
26:     _initAnimation();
27:   }
28: 
29:   @override
30:   void dispose() {
31:     _themeModeNotifier.dispose();
32:     _alignmentController.dispose();
33:     super.dispose();
34:   }
35: 
36:   void _initAnimation() {
37:     _alignmentController = AnimationController(
38:       duration: const Duration(seconds: 2),
39:       vsync: this,
40:     )..repeat(reverse: true);
41:     _alignmentAnimation = _tween.animate(_alignmentController);
42:   }
43: 
44:   @override
45:   Widget build(BuildContext context) {
46:     final ThemeFonts fonts = context.fonts;
47:     final AppLocalizations loc = context.loc;
48: 
49:     return Scaffold(
50:       appBar: AppBar(title: Text(loc.profile)),
51:       body: Padding(
52:         padding: const EdgeInsets.symmetric(vertical: 20),
53:         child: Column(
54:           children: [
55:             ValueListenableBuilder(
56:               valueListenable: _themeModeNotifier,
57:               builder: (BuildContext context, AppThemeMode mode, Widget? child) {
58:                 return ListTile(
59:                   contentPadding: EdgeInsets.only(left: 24),
60:                   leading: Icon(Icons.dark_mode),
61:                   title: child,
62:                   subtitle: Text(
63:                     mode.titleOf(loc),
64:                     style: fonts.regular12,
65:                   ),
66:                   onTap: () async {
67:                     final AppThemeMode? newMode = await ThemeModeSelectorBottomSheet.show(context, mode);
68:                     if (newMode == null) return;
69: 
70:                     _themeModeNotifier.value = newMode;
71:                   },
72:                 );
73:               },
74:               child: Text(
75:                 loc.theme,
76:                 style: fonts.regular16,
77:               ),
78:             ),
79:             const Spacer(),
80:             AlignTransition(
81:               alignment: _alignmentAnimation,
82:               child: ElevatedButton(
83:                 onPressed: () => context.read<SettingsRepository>().setToken(null),
84:                 child: Text(
85:                   loc.logout,
86:                   style: fonts.regular14.copyWith(color: context.colors.red),
87:                 ),
88:               ),
89:             ),
90:           ],
91:         ),
92:       ),
93:     );
94:   }
95: }

